SELECT , u.username FROM `order` o LEFT JOIN sys_user u ON o.user_id = u.id
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.status = #{status}
AND o.user_id = #{userId}
ORDER BY o.create_time DESC

