UPDATE `order`
total_amount = #{totalAmount}, pay_amount = #{payAmount}, status = #{status}, pay_type = #{payType}, pay_time = #{payTime}, delivery_time = #{deliveryTime}, receive_time = #{receiveTime}, close_time = #{closeTime}, remark = #{remark}, receiver_name = #{receiverName}, receiver_phone = #{receiverPhone}, receiver_address = #{receiverAddress}, logistics_no = #{logisticsNo}, logistics_company = #{logisticsCompany},
WHERE id = #{id}

UPDATE `order` 
SET logistics_no = #{logisticsNo}, logistics_company = #{logisticsCompany}
WHERE id = #{id}
